import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as r,c as n,o as s,ag as t,G as i}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse(`{"title":"Google Flow","description":"Google's AI creative studio. Generate short clips, a few seconds to a dozen or so long, from an English prompt, then arrange them into a finished film in Scenebuilder. This page explains whether you can use it, how to make a first video in 10 minutes, how credits are charged and how to avoid the common pitfalls.","frontmatter":{"title":"Google Flow","description":"Google's AI creative studio. Generate short clips, a few seconds to a dozen or so long, from an English prompt, then arrange them into a finished film in Scenebuilder. This page explains whether you can use it, how to make a first video in 10 minutes, how credits are charged and how to avoid the common pitfalls.","domain":"product","tags":["coding-agent"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/gemini/flow.md","filePath":"products/gemini/flow.md","lastUpdated":1795792629000}`),d={name:"products/gemini/flow.md"};function l(h,e,c,g,p,u){const o=r("DocDiagram");return s(),n("div",null,[e[0]||(e[0]=t("",52)),i(o,{src:"/diagrams/google-flow-pipeline.en.svg",alt:"This diagram runs left to right in four stages and answers one question: when you type a sentence or supply a reference image, which model takes it, and how does it become a clip on the timeline? Stage 1 is input, three things: the text prompt, frames (a start frame and an end frame), and ingredients (characters, scenes, objects). Stage 2 is the models. There are two video models, Omni Flash from Gemini Omni and Veo 3.1 Lite from Veo 3.1. They generate and edit video and support conversational iteration, and every generation spends credits, counted per second or per generation. The image models are the Nano Banana family (Pro, 2.1, 2 Lite). They generate and edit images, spend no credits, and follow a daily cap instead. Stage 3 is output: the video models produce candidate clips, and the image models produce images. Stage 4 is the finished film, which is the Scenebuilder timeline. There are six sets of connections. First, the text prompt goes straight into the video models. Second, frames and ingredients can enter the video models together with the same generation. Third, the video models produce candidate clips, and the image models produce images. Fourth, the arrow from candidate clips to Scenebuilder is labelled Add to Scene: only the candidates you pick enter the timeline; the ones you do not pick never do. Fifth, a dashed line along the bottom runs left from the output images back to the input: a generated image can be reused as the start frame, end frame, or ingredient of a later video generation. Sixth, the two-headed dashed line along the top, between the models and Scenebuilder, is Extend: it goes from the end of an existing clip back to the video models, and the continuation it generates returns to the timeline. Inside Scenebuilder, clips sit in order; you can drag them into a different order and trim their start and end. This diagram leaves out which models support which generation mode, because one mode is usually supported by several models, so input is not drawn as one-to-one with any model. It also leaves out specific credit amounts, API call paths, and Flow Music, whose credit system is separate.",width:1080,lang:"en"}),e[1]||(e[1]=t("",146))])}const k=a(d,[["render",l]]);export{y as __pageData,k as default};
